import java.io.IOException;
import java.nio.file.*;
import java.util.stream.Stream;
import static java.nio.file.StandardWatchEventKinds.*;

public class NioDirectoryMonitor {

    // 1. Efficiently walk a directory tree and filter files
    public void processLogFiles(Path startDir) throws IOException {
        // Files.walk returns a Stream that holds an open directory resource; must use try-with-resources
        try (Stream<Path> stream = Files.walk(startDir, 5)) {
            stream.filter(Files::isRegularFile)
                  .filter(path -> path.toString().endsWith(".log"))
                  .forEach(path -> System.out.println("Found log: " + path.toAbsolutePath()));
        }
    }

    // 2. Set up a native WatchService loop to monitor directory changes
    public void monitorDirectory(Path dirToWatch) throws IOException, InterruptedException {
        FileSystem fs = dirToWatch.getFileSystem();

        try (WatchService watchService = fs.newWatchService()) {
            // Register the directory for creation, modification, and deletion events
            dirToWatch.register(watchService, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);
            System.out.println("Monitoring directory: " + dirToWatch);

            boolean keepRunning = true;
            while (keepRunning) {
                // Block until an event is queued by the OS kernel
                WatchKey key = watchService.take();

                for (WatchEvent<?> event : key.pollEvents()) {
                    WatchEvent.Kind<?> kind = event.kind();

                    if (kind == OVERFLOW) {
                        System.err.println("Events lost or discarded due to buffer overflow!");
                        continue;
                    }

                    // The context of a directory watch event is always a relative Path
                    @SuppressWarnings("unchecked")
                    WatchEvent<Path> ev = (WatchEvent<Path>) event;
                    Path filename = ev.context();
                    Path resolvedPath = dirToWatch.resolve(filename);

                    System.out.printf("Event: %s | File: %s%n", kind.name(), resolvedPath);
                }

                // CRITICAL: Reset the key to receive further events. 
                // If reset() returns false, the directory is no longer accessible.
                boolean valid = key.reset();
                if (!valid) {
                    System.out.println("Watch key is invalid. Stopping monitor.");
                    keepRunning = false;
                }
            }
        }
    }
}
